// Generated by WATX Compiler
// WAT + HTML = WATX — A reactive UI framework in WebAssembly

import { createRuntime } from './watx-runtime.js';

export async function createApp(wasmUrl) {
  const runtime = createRuntime();
  const { createSignal, createEffect, batch, h, text, mount } = runtime;

  // Load WebAssembly module
  const wasmResponse = await fetch(wasmUrl);
  const wasmBytes = await wasmResponse.arrayBuffer();
  const wasmModule = await WebAssembly.instantiate(wasmBytes, {});
  const wasm = wasmModule.instance.exports;

  // Create reactive signals backed by WASM globals
  const [seconds, set_seconds] = createSignal(
    () => wasm.signal_get_seconds(),
    (v) => wasm.signal_set_seconds(v),
    0
  );
  const [running, set_running] = createSignal(
    () => wasm.signal_get_running(),
    (v) => wasm.signal_set_running(v),
    0
  );

  // Component: Stopwatch
  function render_Stopwatch() {
    const el_div_0 = h('div');
    el_div_0.setAttribute('class', 'stopwatch');
    const el_h2_1 = h('h2');
    const txt_2 = text('WATX Stopwatch');
    el_h2_1.appendChild(txt_2);
    el_div_0.appendChild(el_h2_1);
    const el_span_3 = h('span');
    el_span_3.setAttribute('class', 'time');
    const reactive_4 = text('');
    createEffect(() => {
      reactive_4.textContent = String(seconds());
    });
    el_span_3.appendChild(reactive_4);
    el_div_0.appendChild(el_span_3);
    const el_span_5 = h('span');
    el_span_5.setAttribute('class', 'unit');
    const txt_6 = text('seconds');
    el_span_5.appendChild(txt_6);
    el_div_0.appendChild(el_span_5);
    const el_div_7 = h('div');
    el_div_7.setAttribute('class', 'buttons');
    const el_button_8 = h('button');
    el_button_8.addEventListener('click', (e) => {
      set_running(1);
    });
    const txt_9 = text('Start');
    el_button_8.appendChild(txt_9);
    el_div_7.appendChild(el_button_8);
    const el_button_10 = h('button');
    el_button_10.addEventListener('click', (e) => {
      set_running(0);
    });
    const txt_11 = text('Stop');
    el_button_10.appendChild(txt_11);
    el_div_7.appendChild(el_button_10);
    const el_button_12 = h('button');
    el_button_12.addEventListener('click', (e) => {
      set_seconds(0);
    });
    const txt_13 = text('Reset');
    el_button_12.appendChild(txt_13);
    el_div_7.appendChild(el_button_12);
    el_div_0.appendChild(el_div_7);
    return el_div_0;
  }

  return {
    Stopwatch: render_Stopwatch,
    mount,
    runtime,
    wasm,
  };
}